toolScript:
let startX, startY;
        let isMeasuring = false;
        const box = document.getElementById('selection-box');
        const emptyState = document.getElementById('empty-state');
        const canvas = document.getElementById('canvas');
        function startMeasure(e) {
            const rect = canvas.getBoundingClientRect();
            startX = e.clientX - rect.left;
            startY = e.clientY - rect.top;
            isMeasuring = true;
            box.style.left = startX + 'px';
            box.style.top = startY + 'px';
            box.style.width = '0px';
            box.style.height = '0px';
            box.classList.remove('hidden');
            emptyState.classList.add('hidden');
        }
        function updateMeasure(e) {
            const rect = canvas.getBoundingClientRect();
            const currX = e.clientX - rect.left;
            const currY = e.clientY - rect.top;
            // Update Cursor Guides
            document.getElementById('guide-v').style.left = currX + 'px';
            document.getElementById('guide-h').style.top = currY + 'px';
            document.getElementById('coord-display').innerText = `X: ${Math.round(currX)}, Y: ${Math.round(currY)}`;
            if (!isMeasuring) return;
            const left = Math.min(currX, startX);
            const top = Math.min(currY, startY);
            const w = Math.abs(currX - startX);
            const h = Math.abs(currY - startY);
            const d = Math.sqrt(w * w + h * h);
            box.style.width = w + 'px';
            box.style.height = h + 'px';
            box.style.left = left + 'px';
            box.style.top = top + 'px';
            document.getElementById('res-w').innerHTML = `${Math.round(w)} <span class="text-sm font-medium text-slate-300 uppercase">px</span>`;
            document.getElementById('res-h').innerHTML = `${Math.round(h)} <span class="text-sm font-medium text-slate-300 uppercase">px</span>`;
            document.getElementById('res-d').innerHTML = `${Math.round(d)} <span class="text-sm font-medium text-slate-500 uppercase">px</span>`;
        }
        function endMeasure() {
            isMeasuring = false;
        }
        // Mobile Touch Support
        function handleTouch(e, type) {
            const touch = e.touches[0];
            const mouseEvent = new MouseEvent(
                type === 'start' ? 'mousedown' : (type === 'move' ? 'mousemove' : 'mouseup'),
                {
                    clientX: touch ? touch.clientX : 0,
                    clientY: touch ? touch.clientY : 0
                }
            );
            if (type === 'end') {
                endMeasure();
            } else {
                canvas.dispatchEvent(mouseEvent);
            }
        }
